// Keyboard value index — record JAH-GPCS-MECHKEYBOARD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"keys": 104, "polling_hz": 1000, "price_usd": 120};
var value = (m.keys*m.polling_hz/1000/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-MECHKEYBOARD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-MECHKEYBOARD-000001|' + value.toFixed(2) + ' value index');

